package com.studenthub.controller;import com.studenthub.dao.PrivateMessageDAO;import com.studenthub.util.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;
@WebServlet(name="PrivateAttachmentServlet",urlPatterns="/messages/attachments/*") public class PrivateAttachmentServlet extends HttpServlet{private final PrivateMessageDAO dao=new PrivateMessageDAO();private final AttachmentStorage storage=new AttachmentStorage();@Override protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{try{String p=q.getPathInfo();if(p==null||!p.matches("/\\d+")){r.sendError(404);return;}var a=dao.attachment(Long.parseLong(p.substring(1)),(Long)q.getSession().getAttribute("userId")).orElse(null);if(a==null){r.sendError(404);return;}var file=storage.find(a.storageKey()).orElse(null);if(file==null){r.sendError(404);return;}MediaResponse.serve(q,r,a,file);}catch(Exception e){if(!r.isCommitted())r.sendError(404);}}}
